pub fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // Produce a non-empty Vec<String> for every input string.
            // We split on '\n'. If the string contains no '\n', we return [s].
            // If it contains '\n', we return the line parts; empty parts are allowed
            // (e.g., trailing '\n' yields an empty last line), but the outer Vec is non-empty.
            if !s.contains('\n') {
                return vec![s];
            }

            let mut out: Vec<String> = Vec::new();

            if keepends {
                // Keep '\n' at the end of each line when it existed in the input.
                let mut start = 0usize;
                for (i, b) in s.as_bytes().iter().enumerate() {
                    if *b == b'\n' {
                        // include the '\n'
                        out.push(s[start..=i].to_string());
                        start = i + 1;
                    }
                }
                // leftover after the last '\n' (possibly empty)
                out.push(s[start..].to_string());
            } else {
                out.extend(s.split('\n').map(|part| part.to_string()));
            }

            // Ensure non-empty inner list even in degenerate cases.
            if out.is_empty() {
                vec![s]
            } else {
                out
            }
        })
        .collect()
}